"use client"

import * as React from "react"
import { ToggleGroup } from "@base-ui/react/toggle-group"
import { Toggle } from "@base-ui/react/toggle"
import { cn } from "cn"

function CheckboxButtonGroup<Value extends string>({
  className,
  ...props
}: ToggleGroup.Props<Value>) {
  return (
    <ToggleGroup
      data-slot="checkbox-button-group"
      multiple
      className={cn("flex flex-wrap gap-2", className)}
      {...props}
    />
  )
}

function RadioButtonGroup<Value extends string>({
  className,
  ...props
}: Omit<ToggleGroup.Props<Value>, "multiple">) {
  return (
    <ToggleGroup
      data-slot="radio-button-group"
      multiple={false}
      className={cn("flex flex-wrap gap-2", className)}
      {...props}
    />
  )
}

function ToggleButton({
  className,
  ...props
}: React.ComponentProps<typeof Toggle>) {
  return (
    <Toggle
      data-slot="toggle-button"
      className={cn(
        "rounded-md border border-border-control px-3 py-1.5 text-sm font-medium text-text-secondary transition-colors duration-fast ease-entrance data-pressed:border-primary data-pressed:bg-tint-indigo data-pressed:text-tint-text-indigo hover:bg-muted",
        className
      )}
      {...props}
    />
  )
}

export { CheckboxButtonGroup, RadioButtonGroup, ToggleButton }

"use client"

import { Toggle as TogglePrimitive } from "@base-ui/react/toggle"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

const toggleVariants = cva(
  "inline-flex items-center justify-center gap-1.5 rounded-md border border-transparent text-sm font-medium text-text-secondary transition-colors duration-fast ease-entrance outline-none hover:bg-muted hover:text-foreground focus-visible:border-ring disabled:pointer-events-none disabled:opacity-40 data-[pressed]:bg-accent data-[pressed]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      size: {
        sm: "h-8 px-2",
        default: "h-9 px-2.5",
        lg: "h-10 px-3",
      },
    },
    defaultVariants: {
      size: "default",
    },
  }
)

function Toggle({
  className,
  size,
  ...props
}: TogglePrimitive.Props & VariantProps<typeof toggleVariants>) {
  return (
    <TogglePrimitive
      data-slot="toggle"
      className={cn(toggleVariants({ size }), className)}
      {...props}
    />
  )
}

export { Toggle, toggleVariants }
